/* Jurong Town Hall — OSM 96764520. Original metre geometry; no image textures.
 * Two chamfered, cantilevered office hulls and the three-faced periscope clock.
 * Upper envelopes follow the OSM plan; lower plates recess under their eaves.
 */
{
const {register,scale,center,lerp}=SGJE;
// Own measured registration height; shared catalogue is regenerated by the lead.
SGJE.data.jurong_town_hall.height=59.3;
SGJE.data.jurong_town_hall.height_source='Measured roof-minus-ground (image-only reference metadata)';
register('jurong_town_hall','裕廊镇大厦','Jurong Town Hall',92,(b,D,G,g)=>{
 const P=D.parts[0].p,stone='#d2d3c9',edge='#e2e2d8',dark='#34474b';
 const cs=.835,ss=.55,to=(u,v)=>[u*cs-v*ss,u*ss+v*cs];
 const poly=Q=>Q.map(p=>to(...p));
 // Exact OSM perimeter is the parapet line. Separate roof plates preserve the
 // narrow central glazed concourse rather than filling it with a solid box.
 const A=P.slice(0,12).map(p=>p.slice()),B=[...P.slice(13),P[12]].map(p=>p.slice());
 // Top reference shows a recessed central service court, with the two long
 // inner eaves separated by about 14 m around a lower square atrium skylight.
 for(const [Q,indices,v]of [[A,[0,11],7],[B,[B.length-2,B.length-1],-7]])for(const i of indices){const u=Q[i][0]*cs+Q[i][1]*ss;Q[i]=to(u,v);}
 function section(Q,inset){const c=center(Q);return Q.map(([x,z])=>{const u=x*cs+z*ss,v=-x*ss+z*cs,cu=c[0]*cs+c[1]*ss,cv=-c[0]*ss+c[1]*cs;return to(cu+(u-cu)*(1-inset/70),cv+(v-cv)*(1-inset/16));});}
 function at(Q,R,t){return Q.map((p,i)=>[lerp(p[0],R[i][0],t),lerp(p[1],R[i][1],t)]);}
 function frustum(Q,R,lo,hi,c){Q.forEach((p,i)=>{const j=(i+1)%Q.length;b.quad(c,[p[0],lo,p[1]],[Q[j][0],lo,Q[j][1]],[R[j][0],hi,R[j][1]],[R[i][0],hi,R[i][1]]);});}
 for(const [ix,Q] of [A,B].entries()){
  const lower=section(Q,5),glass=section(Q,6),top=Q;
  b.prism(glass,0,14.2,dark,2);
  b.facade(glass,1.2,12.6,4.2,2.7,'#547078',edge,.22);
  b.band(lower,5.1,1.2,stone);b.band(lower,11.8,2.7,stone);
  // Freestanding pilotis and slender vertical blades across the lowest office row.
  lower.forEach((p,i)=>{let q=lower[(i+1)%lower.length],L=Math.hypot(q[0]-p[0],q[1]-p[1]);if(L<14)return;let n=Math.round(L/8);for(let k=0;k<=n;k++){const t=k/n,x=lerp(p[0],q[0],t),z=lerp(p[1],q[1],t);b.box(x,0,z,.72,12.6,.72,edge);}});
  // Splayed upper walls: wide solid spandrels alternate with deeply inset
  // ribbon windows. Fins follow the slope, leaving the glazing in shadow.
  for(const [lo,hi,c]of [[14,16.3,stone],[20.3,22,stone],[26.1,28.6,stone]])frustum(at(lower,top,(lo-14)/14.6),at(lower,top,(hi-14)/14.6),lo,hi,c);
  for(const [lo,hi]of [[16.3,20.3],[22,26.1]]){
   const L=at(lower,top,(lo-14)/14.6),U=at(lower,top,(hi-14)/14.6),I=section(L,.9);
   b.walls(I,lo,hi,dark,2);
   L.forEach((p,i)=>{const j=(i+1)%L.length,q=L[j],len=Math.hypot(q[0]-p[0],q[1]-p[1]);if(len<13){b.quad(stone,[p[0],lo,p[1]],[q[0],lo,q[1]],[U[j][0],hi,U[j][1]],[U[i][0],hi,U[i][1]]);return;}const n=Math.round(len/2.65);for(let k=0;k<=n;k++){const t=k/n,a=[lerp(p[0],q[0],t),lo,lerp(p[1],q[1],t)],c=[lerp(U[i][0],U[j][0],t),hi,lerp(U[i][1],U[j][1],t)];b.beam(a,c,.23,edge);}b.beam([p[0],lo,p[1]],[q[0],lo,q[1]],.22,edge);});
  }
  b.cap(top,28.6,'#858d89');b.rim(top,28.8,edge,.38);
  // Fine expansion seams and the rooftop ventilation hoods visible in aerials.
  for(const u of [-40,-20,0,20,40]){const q=to(u,ix?-16:16);if(SGJE.inside(top,...q)){const a=to(u,ix?-28:3),c=to(u,ix?-3:28);b.beam([a[0],28.67,a[1]],[c[0],28.67,c[1]],.09,'#bbc1b8');}}
  for(const u of [-32,32]){const q=to(u,ix?-17:16),R=poly([[u-3,(ix?-17:16)-3],[u+3,(ix?-17:16)-3],[u+3,(ix?-17:16)+3],[u-3,(ix?-17:16)+3]]);frustum(R,scale(R,.60),28.7,34,stone);b.cap(scale(R,.60),34,edge);}
 }
 // Raised central concourse, roof skylight and articulated connecting bridges.
 const C=poly([[-45,-7],[45,-7],[45,7],[-45,7]]);b.prism(C,4.7,25.7,stone);
 const skylight=poly([[-15,-7],[15,-7],[15,7],[-15,7]]);b.prism(skylight,25.7,26.1,'#8faaa6',2);b.rim(skylight,26.2,edge,.3);
 for(let u=-15;u<=15;u+=3){const a=to(u,-7),q=to(u,7);b.beam([a[0],26.18,a[1]],[q[0],26.18,q[1]],.12,edge);}
 for(const u of [-40,32]){const Q=poly([[u-3,-7],[u+3,-7],[u+3,7],[u-3,7]]);b.prism(Q,25.7,28.7,stone);}
 // Median measured main roof is26m. Rescale only the completed body batch;
 // the independently measured59.3m clock below keeps its absolute dimensions.
 for(const bucket of b.buckets.values())for(let i=1;i<bucket.p.length;i+=3)bucket.p[i]=G.base+(bucket.p[i]-G.base)*(26/28.8);
 // Local facade floodlight pass reuses lmMat's height-falling wash, with no
 // self-emission. Office-glass bucket2 continues through the shared helper.
 const wash=new SGJE.Batch(G.base);if(b.buckets.has(0)){wash.buckets.set(0,b.buckets.get(0));b.buckets.delete(0);}
 wash.flush(g,()=>lmMat({c:'#ffffff',vc:true,ds:true,m:0,lc:'#ffe0ad',lk:.34}));
 // Clock shaft and thin terminal blades; displays are blank red lit panels.
 const clockTo=(u,v)=>to(u+33,v+49),clockPoly=Q=>Q.map(p=>clockTo(...p));
 const lamp=new SGJE.Batch(G.base);
 const shaft=clockPoly([[-12,-31],[-8,-31],[-8,-27],[-12,-27]]);lamp.prism(shaft,0,49.2,stone);
 const head=clockPoly([[-14,-32.5],[-6,-32.5],[-6,-27],[-14,-27]]);lamp.prism(head,49.2,57.8,stone);
 const blade=clockPoly([[-14,-32.6],[-6,-32.6],[-6,-31.9],[-14,-31.9]]);lamp.prism(blade,49.2,(x,z)=>58.874+(x*cs+z*ss-23)*.09,edge);
 const blade2=clockPoly([[-14,-32.5],[-13.3,-32.5],[-13.3,-27],[-14,-27]]);lamp.prism(blade2,49.2,(x,z)=>58.774-(-x*ss+z*cs-20)*.15,edge);
 for(let y=30;y<48;y+=3.5){const a=clockTo(-8,-30.1),c=clockTo(-8,-28.9);b.quad(dark,[a[0]+.03,y,a[1]],[c[0]+.03,y,c[1]],[c[0]+.03,y+1.8,c[1]],[a[0]+.03,y+1.8,a[1]]);}
 const clock=new SGJE.Batch(G.base);
 const display=(u0,v0,u1,v1)=>{let a=clockTo(u0,v0),c=clockTo(u1,v1);clock.quad('#7e3b32',[a[0],52.2,a[1]],[c[0],52.2,c[1]],[c[0],53.8,c[1]],[a[0],53.8,a[1]],4);};display(-12.6,-32.66,-7.4,-32.66);display(-14.03,-31.5,-14.03,-28);display(-12.6,-26.96,-7.4,-26.96);
 lamp.flush(g,()=>lmMat({c:'#ffffff',vc:true,ds:true,m:0,lc:'#ffe4b4',lk:.22,glow:'#ffe4b4',gk:.12}));
 clock.flush(g,()=>lmMat({c:'#ffffff',vc:true,ds:true,m:0,lc:'#e14522',lk:1.1,glow:'#e14522',gk:.45}));
 // Two stair and entrance platforms tucked under the long outer facade.
 for(const u of [-30,27]){const c=to(u,26),Q=poly([[u-5,23],[u+5,23],[u+5,30],[u-5,30]]);b.prism(Q,4.6,5.1,stone);for(let i=0;i<15;i++){const q=to(u-5+i*.65,30);b.box(q[0],i*.30,q[1],.78,.3,4.5,stone,-Math.atan2(ss,cs));}}
 // Restrained planting, kept within the monument footprint.
 for(const [u,v]of [[-42,27],[38,27],[-39,-29],[39,-27]]){let q=to(u,v);b.box(q[0],0,q[1],4,.5,2,'#9da68e',-.58);}
});
}
